  ["yP"] = "Anyone got some cookies for me?",
  ["yQ"] = "Do you need help? Just ask me about anything you'd like to know!",
  ["yR"] = "I'm buying all of your blueberries for my famous blueberry juice!",
  ["yS"] = "Hold your tongue.",
  ["yT"] = "Goodbye, |PLAYERNAME|.",
  ["yU"] = "Greetings, |PLAYERNAME|.",
